import sys
import re


def is_number(s):
    if not s or (s[0] != '-' and (s[0] != '+' and (s[0] != '' and not s[0].isdigit())))
        or (s[-1] == '.' and not s[-2].isdigit()):
        return False
    if s[0] == '-':
        s = s[1:]
    if '.' in s:
        parts = s.split('.')
        if len(parts) > 2 or not parts[1].isdigit():
            return False
    return s.isdigit()


def main():
    rows = []
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        cells = line.split("|")
        cells = [cell.strip() for cell in cells]
        if not cells:
            continue
        rows.append(cells)

    if not rows:
        return

    headers = rows[0]
    data_rows = rows[1:]

    # Calculate widths
    widths = []
    for column_idx in range(len(headers)):
        column_cells = [headers[column_idx]] + [row[column_idx] for row in data_rows]
        max_len = max(len(cell) for cell in column_cells if cell)
        widths.append(max_len if max_len > 0 else 1)

    def fmt(row):
        padded_cells = []
        for column_idx in range(len(row)):
            cell = row[column_idx]
            width = widths[column_idx]
            if is_number(cell):
                padded_cell = cell.rjust(width)
            else:
                padded_cell = cell.ljust(width)
            padded_cells.append(padded_cell)
        return " | ".join(padded_cells)

    print(fmt(headers))
    separator = "-+-".join("-" * w for w in widths)
    print(separator)
    for row in data_rows:
        print(fmt(row))


if __name__ == "__main__":
    main()
